#[verifier::spec]
fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>) -> Vec<i32> {
    // Precondition: All input vectors must have the same length
    // Requires: s1.len() == s2.len() && s2.len() == s3.len()
    // Ensures: The resulting vector has a length of 3 * s1.len()
    // Ensures: The resulting vector is an interleaving of s1, s2, and s3
    #[requires(s1.len() == s2.len() && s2.len() == s3.len())]
    #[ensures(res.len() == 3 * s1.len())]
    #[ensures(forall(|i: usize| i < s1.len() ==> res[3 * i] == s1[i] && res[3 * i + 1] == s2[i] && res[3 * i + 2] == s3[i]))]
    let n = s1.len();
    let mut res = Vec::with_capacity(3 * n);
    
    // Invariant: The length of res is always 3 * i during the loop
    // Decreases: n - i
    for i in 0..n {
        // Invariant: res.len() == 3 * i
        res.push(s1[i]);
        res.push(s2[i]);
        res.push(s3[i]);
    }
    
    res
}